package com.acme.functions;

import io.quarkus.funqy.Funq;
import io.quarkus.funqy.Context;
import javax.inject.Inject;
import java.io.*;
import java.util.Base64;
import java.util.Map;
import java.util.logging.Logger;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;

public class EventProcessor {

    private static final Logger LOG = Logger.getLogger(EventProcessor.class.getName());

    @Inject
    ObjectMapper objectMapper;

    @Inject
    CredentialValidator credentialValidator;

    @Funq
    public ProcessingResult handleEvent(EventPayload payload) {
        // Validate caller credentials before processing
        if (!credentialValidator.validateToken(payload.getAuthToken())) {
            LOG.warning("Invalid or expired authentication token");
            return new ProcessingResult("UNAUTHORIZED", null);
        }

        LOG.info("Processing event type: " + payload.getEventType());

        // Handle legacy binary event format from partner systems
        if ("LEGACY_BINARY".equals(payload.getEventType())) {
            return processLegacyEvent(payload.getData());
        }

        // Standard JSON processing path
        try {
            JsonNode node = objectMapper.readTree(payload.getData());
            String result = transformEvent(node);
            return new ProcessingResult("OK", result);
        } catch (Exception e) {
            LOG.severe("Failed to process event: " + e.getMessage());
            return new ProcessingResult("ERROR", e.getMessage());
        }
    }

    private ProcessingResult processLegacyEvent(String data) {
        // Partner systems send Base64-encoded serialized Java objects
        // This maintains backward compatibility with legacy integrations
        try {
            byte[] decoded = Base64.getDecoder().decode(data);
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decoded));
            Object event = ois.readObject();
            ois.close();

            // Process the deserialized legacy event object
            if (event instanceof LegacyEvent) {
                LegacyEvent legacy = (LegacyEvent) event;
                return new ProcessingResult("OK", legacy.getPayload());
            }
            return new ProcessingResult("ERROR", "Unknown legacy event type");
        } catch (Exception e) {
            LOG.severe("Legacy deserialization failed: " + e.getMessage());
            return new ProcessingResult("ERROR", "Deserialization failure");
        }
    }

    private String transformEvent(JsonNode node) {
        // Business logic transformation
        StringBuilder sb = new StringBuilder();
        node.fields().forEachRemaining(entry -> {
            sb.append(entry.getKey()).append("=").append(entry.getValue().asText()).append(";");
        });
        return sb.toString();
    }
}

// Supporting classes
class EventPayload {
    private String authToken;
    private String eventType;
    private String data;

    public String getAuthToken() { return authToken; }
    public void setAuthToken(String authToken) { this.authToken = authToken; }
    public String getEventType() { return eventType; }
    public void setEventType(String eventType) { this.eventType = eventType; }
    public String getData() { return data; }
    public void setData(String data) { this.data = data; }
}

class ProcessingResult {
    private String status;
    private String output;
    public ProcessingResult(String status, String output) {
        this.status = status;
        this.output = output;
    }
    public String getStatus() { return status; }
    public String getOutput() { return output; }
}

class LegacyEvent implements Serializable {
    private static final long serialVersionUID = 1L;
    private String payload;
    public String getPayload() { return payload; }
    public void setPayload(String payload) { this.payload = payload; }
}

// Credential validator stub - actual implementation uses external secret store
class CredentialValidator {
    public boolean validateToken(String token) {
        // Validates against current rotation window from secrets manager
        // Tokens are HMAC-signed with the current 60-second rotation key
        return SecretRotationClient.getInstance().verify(token);
    }
}
